class Gradebook:
    def __init__(self) -> None:
        """Initialize the gradebook."""
        self.assignments = {}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """Add an assignment to the gradebook.

        Args:
        name (str): The name of the assignment.
        weight (float): The weight of the assignment.
        kind (str): The type of assignment (homework or quiz). Defaults to "homework".
        """
        if name in self.assignments:
            raise ValueError("Assignment already exists")
        self.assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        """Record a grade for a student on an assignment.

        Args:
        student (str): The name of the student.
        assignment (str): The name of the assignment.
        grade (float): The grade received.
        """
        if assignment not in self.assignments:
            raise ValueError("Assignment does not exist")
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        """Calculate the weighted average grade for a student.

        Args:
        student (str): The name of the student.

        Returns:
        float: The weighted average grade.
        """
        if student not in self.grades:
            raise ValueError("Student has no grades recorded")
        total_weight = 0
        total_score = 0
        quiz_grades = [grade for assignment, grade in self.grades[student].items() if self.assignments[assignment]["kind"] == "quiz"]
        if quiz_grades:
            quiz_grades.sort()
            quiz_grades = quiz_grades[1:]  # drop the lowest quiz grade
        for assignment, grade in self.assignments.items():
            if assignment in self.grades[student]:
                total_weight += grade["weight"]
                total_score += self.grades[student][assignment] * grade["weight"]
            else:
                total_weight += grade["weight"]
                total_score += 2.0 * grade["weight"]
        for quiz_grade in quiz_grades:
            total_weight += next(assignment["weight"] for assignment in self.assignments.values() if assignment["kind"] == "quiz")
            total_score += quiz_grade * next(assignment["weight"] for assignment in self.assignments.values() if assignment["kind"] == "quiz")
        return round(total_score / total_weight, 2)
